// Mirrors contracts/schemas.py (CONTRACT_VERSION 1.1.0) field for field.
// Do not change shapes here without a contract change (CLAUDE.md rule 4).
//
// Pydantic always serialises every field, so fields with defaults are present
// in the JSON: they are required here, and `X | None = None` becomes `X | null`.

export const CONTRACT_VERSION = "1.1.0";

export type SourceRank = "PRIMARY" | "FILING" | "PRESS" | "AGGREGATOR" | "UNKNOWN";

export interface Source {
  name: string;
  url: string | null;
  date: string | null; // ISO date or partial ("2025-10")
  rank: SourceRank;
}

export interface EntityRef {
  id: string; // Cala UUID
  name: string;
  type: string; // Company | Organization | Person | FundingRound ...
  description: string | null;
}

export interface Company extends EntityRef {
  industries: string[];
  stage: string | null;
  country: string | null;
  total_funding_text: string | null;
  sources: Source[];
}

export interface RoundInvestor {
  investor: EntityRef;
  is_lead: boolean | null; // null = unknown
}

export interface Round {
  id: string;
  company_id: string;
  label: string | null; // "Seed", "Series A" ...
  date: string | null;
  amount_text: string | null;
  amount_eur: number | null;
  investors: RoundInvestor[];
  sources: Source[];
}

export interface PortfolioLink {
  investor_id: string;
  company: EntityRef;
  sources: Source[];
}

export type PersonRole = "BOARD" | "FOUNDER" | "CEO" | "EMPLOYEE";

export interface PersonLink {
  person: EntityRef;
  company_id: string;
  role: PersonRole;
  sources: Source[];
}

export interface Competitor {
  company: Company;
  reason: string;
  similarity: number | null;
}

export type ConflictKind = "PORTFOLIO" | "BOARD";

export interface Conflict {
  kind: ConflictKind;
  competitor: EntityRef;
  via_person: EntityRef | null;
  sources: Source[];
}

export interface Reason {
  text: string;
  sources: Source[];
}

export type LeadData = "known" | "partial" | "unknown";

export interface InvestorScore {
  investor: EntityRef;
  score: number; // 0-100, higher = better fit
  conflicts: Conflict[]; // non-empty = this investor belongs in `skip`
  leads_in_space: number;
  rounds_in_space: number;
  // "known" = every round in space says who led, "partial" = some do,
  // "unknown" = none do (show rounds_in_space, say so).
  lead_data: LeadData;
  last_lead_date: string | null;
  deals_last_12m: number | null; // null = unknown
  warm_paths: Reason[];
  reasons: Reason[];
}

export interface FounderReport {
  company: Company;
  competitors: Competitor[];
  pitch: InvestorScore[]; // no conflicts; sorted by score, highest first
  skip: InvestorScore[]; // one or more conflicts; sorted by score, highest first
}

export interface InvestorCheck {
  investor: EntityRef;
  company: Company;
  conflicts: Conflict[];
  competitors: Competitor[];
  rounds: Round[]; // rounds of `company` AND of every competitor; group by Round.company_id
}

export interface Brief {
  investor_id: string;
  company_id: string;
  markdown: string; // cites with [n] markers: n is a 1-based index into `citations`
  citations: Source[];
}

export type AgentEventType = "step" | "text" | "brief" | "error" | "done";

export interface AgentEvent {
  // step = progress line, text = answer chunk (append to the previous ones),
  // brief = one finished brief, error = something failed, done = end of stream
  type: AgentEventType;
  message: string | null;
  brief: Brief | null;
  investor_name: string | null; // slush-prep: the pasted name this event belongs to
  investor: EntityRef | null; // slush-prep: the resolved investor, once known
  citations: Source[]; // chat: sent on `done`; [n] in the text is a 1-based index into it
}

// --- REST bodies and small responses (contracts/api.md) ----------------------

export type EntityKind = "company" | "investor";

export interface ResolveRequest {
  name: string;
  kind: EntityKind;
}

export interface FounderAnalyzeRequest {
  company_id: string;
  competitor_ids?: string[];
}

export interface InvestorCheckRequest {
  investor_id: string;
  company_id: string;
}

export interface BriefRequest {
  investor_id: string;
  company_id: string;
}

export interface SlushPrepRequest {
  company_id: string;
  investor_names: string[];
}

export interface SlushPrepResponse {
  job_id: string;
}

export interface ChatRequest {
  company_id?: string;
  investor_id?: string;
  message: string;
}

export interface HealthResponse {
  ok: true;
  contract_version: string;
}

export interface ApiErrorBody {
  error: string;
}

// Parser for the contract's SSE wire format (contracts/api.md → Streams):
// one `data: <AgentEvent JSON>\n\n` per event, no named events, no ids.
// Works on any byte stream, so it serves both GET streams and POST /api/chat.

import type { AgentEvent } from "./types";

export async function* parseAgentEvents(
  body: ReadableStream<Uint8Array>,
): AsyncGenerator<AgentEvent> {
  const reader = body.pipeThrough(new TextDecoderStream()).getReader();
  let buffer = "";
  try {
    while (true) {
      const { value, done } = await reader.read();
      if (value) buffer += value.replace(/\r\n?/g, "\n");
      let end: number;
      while ((end = buffer.indexOf("\n\n")) !== -1) {
        const event = parseBlock(buffer.slice(0, end));
        buffer = buffer.slice(end + 2);
        if (event) {
          yield event;
          if (event.type === "done") return;
        }
      }
      if (done) {
        const event = parseBlock(buffer);
        if (event) yield event;
        return;
      }
    }
  } finally {
    reader.releaseLock();
  }
}

// One SSE block → event. Multi-line `data:` fields are joined with "\n" per the
// SSE spec; comment lines (":") and other fields are ignored.
function parseBlock(block: string): AgentEvent | null {
  const data = block
    .split("\n")
    .filter((line) => line.startsWith("data:"))
    .map((line) => line.slice(5).replace(/^ /, ""));
  if (data.length === 0) return null;
  return JSON.parse(data.join("\n")) as AgentEvent;
}

import assert from "node:assert/strict";
import { test } from "node:test";

import { parseAgentEvents } from "./sse.ts";
import type { AgentEvent } from "./types.ts";

function ev(partial: Partial<AgentEvent> & Pick<AgentEvent, "type">): AgentEvent {
  return {
    message: null,
    brief: null,
    investor_name: null,
    investor: null,
    citations: [],
    ...partial,
  };
}

function streamOf(chunks: string[]): ReadableStream<Uint8Array> {
  const enc = new TextEncoder();
  return new ReadableStream({
    start(controller) {
      for (const c of chunks) controller.enqueue(enc.encode(c));
      controller.close();
    },
  });
}

async function collect(chunks: string[]): Promise<AgentEvent[]> {
  const out: AgentEvent[] = [];
  for await (const e of parseAgentEvents(streamOf(chunks))) out.push(e);
  return out;
}

const step = ev({ type: "step", message: "resolve_company(Kelluu)" });
const text = ev({ type: "text", message: "NATO Innovation Fund led [1]." });
const done = ev({
  type: "done",
  citations: [{ name: "Press", url: "https://example.com", date: "2025-10", rank: "PRESS" }],
});

test("parses one event per data block, in order", async () => {
  const wire = [step, text, done].map((e) => `data: ${JSON.stringify(e)}\n\n`).join("");
  assert.deepEqual(await collect([wire]), [step, text, done]);
});

test("handles events split across chunks", async () => {
  const wire = `data: ${JSON.stringify(step)}\n\ndata: ${JSON.stringify(done)}\n\n`;
  const chunks = wire.match(/.{1,7}/gs) ?? [];
  assert.deepEqual(await collect(chunks), [step, done]);
});

test("stops after done, ignores comments and CRLF", async () => {
  const wire =
    `: keep-alive\r\n\r\n` +
    `data: ${JSON.stringify(step)}\r\n\r\n` +
    `data: ${JSON.stringify(done)}\r\n\r\n` +
    `data: ${JSON.stringify(text)}\r\n\r\n`;
  assert.deepEqual(await collect([wire]), [step, done]);
});

test("flushes a final event without a trailing blank line", async () => {
  assert.deepEqual(await collect([`data: ${JSON.stringify(done)}`]), [done]);
});

// The only module that talks to the backend; components never call fetch directly.
//
// In the browser, requests go to same-origin `/api/*`, which next.config.ts
// rewrites to `${API_URL}/api/*` (B's server, or C's mock on another port).
// On the server (server components, route handlers) we call API_URL directly.

import { parseAgentEvents } from "./sse";
import type {
  AgentEvent,
  Brief,
  BriefRequest,
  ChatRequest,
  EntityKind,
  EntityRef,
  FounderAnalyzeRequest,
  FounderReport,
  HealthResponse,
  InvestorCheck,
  InvestorCheckRequest,
  SlushPrepRequest,
  SlushPrepResponse,
} from "./types";

export class ApiError extends Error {
  constructor(
    message: string,
    readonly status: number,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

function baseUrl(): string {
  if (typeof window !== "undefined") return "";
  return (process.env.API_URL ?? "http://localhost:8000").replace(/\/+$/, "");
}

async function request(path: string, init: RequestInit = {}): Promise<Response> {
  let res: Response;
  try {
    res = await fetch(`${baseUrl()}${path}`, {
      ...init,
      headers: { "Content-Type": "application/json", ...init.headers },
      cache: "no-store",
    });
  } catch {
    throw new ApiError("Can't reach the Pitchlist server.", 0);
  }
  if (!res.ok) {
    let message = `Request failed (${res.status}).`;
    try {
      const body = (await res.json()) as { error?: unknown };
      if (typeof body.error === "string" && body.error) message = body.error;
    } catch {
      // not a JSON error body; keep the generic message
    }
    throw new ApiError(message, res.status);
  }
  return res;
}

async function getJson<T>(path: string, signal?: AbortSignal): Promise<T> {
  return (await request(path, { signal })).json() as Promise<T>;
}

async function postJson<T>(path: string, body: unknown, signal?: AbortSignal): Promise<T> {
  const res = await request(path, { method: "POST", body: JSON.stringify(body), signal });
  return res.json() as Promise<T>;
}

async function* stream(res: Response): AsyncGenerator<AgentEvent> {
  if (!res.body) throw new ApiError("The server sent an empty stream.", res.status);
  yield* parseAgentEvents(res.body);
}

// --- Routes (contracts/api.md) -----------------------------------------------

export function health(signal?: AbortSignal): Promise<HealthResponse> {
  return getJson("/api/health", signal);
}

export function resolve(name: string, kind: EntityKind, signal?: AbortSignal): Promise<EntityRef[]> {
  return postJson("/api/resolve", { name, kind }, signal);
}

export function analyzeFounder(
  body: FounderAnalyzeRequest,
  signal?: AbortSignal,
): Promise<FounderReport> {
  return postJson("/api/founder/analyze", body, signal);
}

export function checkInvestor(
  body: InvestorCheckRequest,
  signal?: AbortSignal,
): Promise<InvestorCheck> {
  return postJson("/api/investor/check", body, signal);
}

export function getBrief(body: BriefRequest, signal?: AbortSignal): Promise<Brief> {
  return postJson("/api/brief", body, signal);
}

export function startSlushPrep(
  body: SlushPrepRequest,
  signal?: AbortSignal,
): Promise<SlushPrepResponse> {
  return postJson("/api/slush-prep", body, signal);
}

/** Events of a slush-prep job, in order; ends after the `done` event. */
export async function* jobEvents(jobId: string, signal?: AbortSignal): AsyncGenerator<AgentEvent> {
  const res = await request(`/api/jobs/${encodeURIComponent(jobId)}/stream`, {
    headers: { Accept: "text/event-stream" },
    signal,
  });
  yield* stream(res);
}

/** Streams a chat answer: `text` chunks, then `done` carrying the citations. */
export async function* chat(body: ChatRequest, signal?: AbortSignal): AsyncGenerator<AgentEvent> {
  const res = await request("/api/chat", {
    method: "POST",
    body: JSON.stringify(body),
    headers: { Accept: "text/event-stream" },
    signal,
  });
  yield* stream(res);
}

import type { NextConfig } from "next";

// The repo keeps one .env at the root (CLAUDE.md → Setup). Load it for API_URL
// unless the variable is already set; a missing file is fine.
if (!process.env.API_URL) {
  try {
    process.loadEnvFile("../.env");
  } catch {
    // no root .env; fall back to the default below
  }
}

const API_URL = (process.env.API_URL ?? "http://localhost:8000").split("#")[0].trim().replace(/\/+$/, "");
process.env.API_URL = API_URL;

const nextConfig: NextConfig = {
  cacheComponents: true,
  partialPrefetching: true,
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
  // Browser calls same-origin /api/*; this forwards them to B's server or C's mock
  // (no CORS, and switching backends is just API_URL).
  async rewrites() {
    return [{ source: "/api/:path*", destination: `${API_URL}/api/:path*` }];
  },
};

export default nextConfig;

import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import Link from "next/link";
import "./globals.css";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  title: "Pitchlist",
  description: "Who's a fit, and who has a conflict, from either side of the table. Built on Cala.",
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html lang="en" className={`${geistSans.variable} ${geistMono.variable} h-full antialiased`}>
      <body className="flex min-h-full flex-col">
        <header className="border-b border-line">
          <div className="mx-auto flex h-14 w-full max-w-5xl items-center justify-between px-4">
            <Link href="/" className="text-base font-semibold tracking-tight">
              Pitchlist
            </Link>
            <span className="text-sm text-muted">Sourced from Cala</span>
          </div>
        </header>
        <main className="mx-auto w-full max-w-5xl flex-1 px-4 py-8">{children}</main>
      </body>
    </html>
  );
}

