// Mock of B's REST API (contracts/api.md), served from contracts/fixtures/models/.
// Pure request → response logic; mock/server.ts wraps it in an HTTP server.
// The founder/check/brief/event files are A's *samples* (real facts, placeholder
// ranking); B's API replaces them at CP3 (task C8).

import { readFileSync } from "node:fs";
import { join } from "node:path";

import type {
  AgentEvent,
  Brief,
  EntityKind,
  EntityRef,
  FounderReport,
  InvestorCheck,
  InvestorScore,
} from "../lib/types.ts";

export interface IndexEntity extends EntityRef {
  kind: EntityKind;
}

export interface FixtureIndex {
  contract_version: string;
  aliases: Record<string, string>;
  entities: IndexEntity[];
  files: string[];
}

export type MockResult =
  | { kind: "json"; status: number; body: unknown }
  | { kind: "stream"; events: AgentEvent[] };

/** Same rule as backend/data/mappers.py `slug()`. */
export function slug(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

const json = (body: unknown, status = 200): MockResult => ({ kind: "json", status, body });
const error = (status: number, message: string): MockResult => json({ error: message }, status);

function str(v: unknown): string | null {
  return typeof v === "string" && v.trim() ? v.trim() : null;
}

export class MockApi {
  private index: FixtureIndex;
  private files: Set<string>;
  private jobs = new Map<string, AgentEvent[]>();
  private nextJob = 1;

  constructor(private dir: string) {
    this.index = this.read<FixtureIndex>("index.json");
    this.files = new Set(this.index.files);
  }

  private read<T>(file: string): T {
    return JSON.parse(readFileSync(join(this.dir, file), "utf8")) as T;
  }

  private tryRead<T>(file: string): T | null {
    return this.files.has(file) ? this.read<T>(file) : null;
  }

  /** Cala has several IDs for one firm; fixtures are keyed by the canonical one. */
  private canonical(id: string): string {
    return this.index.aliases[id] ?? id;
  }

  handle(method: string, path: string, body: Record<string, unknown> = {}): MockResult {
    const route = `${method} ${path.replace(/\/+$/, "")}`;
    const job = /^GET \/api\/jobs\/([^/]+)\/stream$/.exec(route);
    if (job) return this.jobStream(decodeURIComponent(job[1]));

    switch (route) {
      case "GET /api/health":
        return json({ ok: true, contract_version: this.index.contract_version });
      case "POST /api/resolve":
        return this.resolve(body);
      case "POST /api/founder/analyze":
        return this.founder(body);
      case "POST /api/investor/check":
        return this.investorCheck(body);
      case "POST /api/brief":
        return this.brief(body);
      case "POST /api/slush-prep":
        return this.slushPrep(body);
      case "POST /api/chat":
        return str(body.message)
          ? { kind: "stream", events: this.read<AgentEvent[]>("agent_events_chat.json") }
          : error(422, "message is required");
      default:
        return error(404, `No route ${route}`);
    }
  }

  private resolve(body: Record<string, unknown>): MockResult {
    const name = str(body.name);
    const kind = body.kind;
    if (!name) return error(422, "name is required");
    if (kind !== "company" && kind !== "investor") {
      return error(422, 'kind must be "company" or "investor"');
    }
    const s = slug(name);
    const recorded = this.tryRead<EntityRef[]>(`resolve_${kind}_${s}.json`);
    if (recorded) return json(recorded);
    // Not a recorded search: fuzzy match on every entity the fixtures know.
    const hits = this.index.entities
      .filter((e) => e.kind === kind && s && slug(e.name).includes(s))
      .slice(0, 10)
      .map(({ id, name, type, description }) => ({ id, name, type, description }));
    return json(hits);
  }

  private founder(body: Record<string, unknown>): MockResult {
    const id = str(body.company_id);
    if (!id) return error(422, "company_id is required");
    const report = this.tryRead<FounderReport>(`founder_report_${this.canonical(id)}.json`);
    if (!report) return error(404, "The mock has no founder report for this company.");
    const ids = body.competitor_ids;
    if (!Array.isArray(ids)) return json(report);
    return json(restrictToCompetitors(report, new Set(ids.map(String))));
  }

  private investorCheck(body: Record<string, unknown>): MockResult {
    const inv = str(body.investor_id);
    const co = str(body.company_id);
    if (!inv || !co) return error(422, "investor_id and company_id are required");
    const check = this.tryRead<InvestorCheck>(
      `investor_check_${this.canonical(inv)}_${this.canonical(co)}.json`,
    );
    return check ? json(check) : error(404, "The mock has no investor check for this pair.");
  }

  private brief(body: Record<string, unknown>): MockResult {
    const inv = str(body.investor_id);
    const co = str(body.company_id);
    if (!inv || !co) return error(422, "investor_id and company_id are required");
    const brief = this.tryRead<Brief>(`brief_${this.canonical(inv)}_${this.canonical(co)}.json`);
    return brief ? json(brief) : error(404, "The mock has no brief for this pair.");
  }

  private slushPrep(body: Record<string, unknown>): MockResult {
    const names = body.investor_names;
    if (!str(body.company_id)) return error(422, "company_id is required");
    if (!Array.isArray(names) || names.length === 0) {
      return error(422, "investor_names must be a non-empty list");
    }
    // The recorded stream is replayed whatever names were pasted.
    const id = `mock-job-${this.nextJob++}`;
    this.jobs.set(id, this.read<AgentEvent[]>("agent_events_slush_prep.json"));
    return json({ job_id: id });
  }

  private jobStream(id: string): MockResult {
    const events = this.jobs.get(id);
    return events ? { kind: "stream", events } : error(404, `No job ${id}`);
  }
}

/**
 * What B does with `competitor_ids`: rank against exactly those competitors.
 * The mock approximates it: drop the other competitors and the conflicts that
 * pointed at them; a Skip investor left with no conflict moves to Pitch.
 */
export function restrictToCompetitors(report: FounderReport, keep: Set<string>): FounderReport {
  const competitors = report.competitors.filter((c) => keep.has(c.company.id));
  const pitch: InvestorScore[] = [...report.pitch];
  const skip: InvestorScore[] = [];
  for (const s of report.skip) {
    const conflicts = s.conflicts.filter((c) => keep.has(c.competitor.id));
    (conflicts.length ? skip : pitch).push({ ...s, conflicts });
  }
  const byScore = (a: InvestorScore, b: InvestorScore) => b.score - a.score;
  return { ...report, competitors, pitch: pitch.sort(byScore), skip: skip.sort(byScore) };
}

// Mock API server for frontend work before B's API is live (task C2).
//
//   npm run mock                      # http://localhost:8001
//   API_URL=http://localhost:8001 npm run dev
//
// Env: MOCK_PORT (8001), MOCK_DELAY_MS (400, latency for JSON routes so loading
// states show), MOCK_STEP_MS (350, gap between streamed events).
// Add ?mock_error=<status> to any request to get that error, for error states.

import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { MockApi } from "./handlers.ts";

const here = dirname(fileURLToPath(import.meta.url));
const FIXTURES = process.env.MOCK_FIXTURES ?? join(here, "../../contracts/fixtures/models");
const PORT = Number(process.env.MOCK_PORT ?? 8001);
const DELAY_MS = Number(process.env.MOCK_DELAY_MS ?? 400);
const STEP_MS = Number(process.env.MOCK_STEP_MS ?? 350);

const api = new MockApi(FIXTURES);
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "Content-Type, Accept",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
};

async function readBody(req: IncomingMessage): Promise<Record<string, unknown> | null> {
  let raw = "";
  for await (const chunk of req) raw += chunk;
  if (!raw.trim()) return {};
  try {
    const parsed: unknown = JSON.parse(raw);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed)
      ? (parsed as Record<string, unknown>)
      : null;
  } catch {
    return null;
  }
}

function sendJson(res: ServerResponse, status: number, body: unknown) {
  res.writeHead(status, { ...CORS, "Content-Type": "application/json" });
  res.end(JSON.stringify(body));
}

async function handle(req: IncomingMessage, res: ServerResponse) {
  const url = new URL(req.url ?? "/", "http://mock");
  const method = req.method ?? "GET";
  if (method === "OPTIONS") {
    res.writeHead(204, CORS);
    return res.end();
  }

  const forced = Number(url.searchParams.get("mock_error"));
  if (forced >= 400) {
    await sleep(DELAY_MS);
    return sendJson(res, forced, { error: `Mock error ${forced} (requested with ?mock_error).` });
  }

  const body = method === "POST" ? await readBody(req) : {};
  if (body === null) return sendJson(res, 422, { error: "Body must be a JSON object." });

  const result = api.handle(method, url.pathname, body);
  if (result.kind === "json") {
    await sleep(DELAY_MS);
    return sendJson(res, result.status, result.body);
  }

  res.writeHead(200, {
    ...CORS,
    "Content-Type": "text/event-stream",
    "Cache-Control": "no-cache",
    Connection: "keep-alive",
  });
  let closed = false;
  req.on("close", () => (closed = true));
  for (const event of result.events) {
    await sleep(STEP_MS);
    if (closed) return;
    res.write(`data: ${JSON.stringify(event)}\n\n`);
  }
  res.end();
}

createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error(err);
    if (!res.headersSent) sendJson(res, 500, { error: "Mock server error." });
    else res.end();
  });
}).listen(PORT, () => {
  console.log(`Pitchlist mock API on http://localhost:${PORT} (fixtures: ${FIXTURES})`);
});

import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

import type { AgentEvent, EntityRef, FounderReport } from "../lib/types.ts";
import { MockApi, restrictToCompetitors, slug, type FixtureIndex } from "./handlers.ts";

const DIR = join(dirname(fileURLToPath(import.meta.url)), "../../contracts/fixtures/models");
const index = JSON.parse(readFileSync(join(DIR, "index.json"), "utf8")) as FixtureIndex & {
  founder_mode: { company_id: string }[];
  investor_mode: { investor_id: string; company_id: string }[];
  briefs: { investor_id: string; company_id: string }[];
};
const api = new MockApi(DIR);

function ok<T>(method: string, path: string, body?: Record<string, unknown>): T {
  const r = api.handle(method, path, body);
  assert.equal(r.kind, "json");
  if (r.kind !== "json") throw new Error("unreachable");
  assert.equal(r.status, 200, JSON.stringify(r.body));
  return r.body as T;
}

function status(method: string, path: string, body?: Record<string, unknown>): number {
  const r = api.handle(method, path, body);
  return r.kind === "json" ? r.status : 200;
}

test("slug matches the backend rule", () => {
  assert.equal(slug("SNÖ Ventures"), "sn-ventures");
  assert.equal(slug("  Maki.vc "), "maki-vc");
  assert.equal(slug("Nordic Air Defence"), "nordic-air-defence");
});

test("health reports the contract version", () => {
  assert.deepEqual(ok("GET", "/api/health"), { ok: true, contract_version: "1.1.0" });
});

test("resolve: recorded searches, fuzzy fallback, validation", () => {
  const tesi = ok<EntityRef[]>("POST", "/api/resolve", { name: "Tesi", kind: "investor" });
  assert.equal(tesi[0].id, "df5be140-d50e-4e21-bb4f-d8f1e4ad3959");
  const fuzzy = ok<EntityRef[]>("POST", "/api/resolve", { name: "aavu", kind: "company" });
  assert.ok(fuzzy.some((e) => e.name === "Aavuus"));
  assert.ok(fuzzy.every((e) => Object.keys(e).sort().join() === "description,id,name,type"));
  assert.deepEqual(ok("POST", "/api/resolve", { name: "zzzz-none", kind: "company" }), []);
  assert.equal(status("POST", "/api/resolve", { name: "Tesi", kind: "fund" }), 422);
  assert.equal(status("POST", "/api/resolve", { kind: "company" }), 422);
});

test("every demo founder report, check and brief is served", () => {
  for (const f of index.founder_mode) {
    const r = ok<FounderReport>("POST", "/api/founder/analyze", { company_id: f.company_id });
    assert.equal(r.company.id, f.company_id);
  }
  for (const c of index.investor_mode) ok("POST", "/api/investor/check", { ...c });
  for (const b of index.briefs) ok("POST", "/api/brief", { ...b });
});

test("alias IDs resolve to the canonical fixture", () => {
  const [alias, canonical] = Object.entries(index.aliases).find(([, c]) =>
    index.founder_mode.some((f) => f.company_id === c),
  )!;
  const r = ok<FounderReport>("POST", "/api/founder/analyze", { company_id: alias });
  assert.equal(r.company.id, canonical);
});

test("unknown entities are 404 with an error message", () => {
  for (const [path, body] of [
    ["/api/founder/analyze", { company_id: "nope" }],
    ["/api/investor/check", { investor_id: "nope", company_id: "nope" }],
    ["/api/brief", { investor_id: "nope", company_id: "nope" }],
  ] as const) {
    const r = api.handle("POST", path, body);
    assert.ok(r.kind === "json" && r.status === 404 && typeof (r.body as { error: string }).error === "string");
  }
  assert.equal(status("GET", "/api/nothing"), 404);
});

test("competitor_ids: removing a competitor drops it and its conflicts", () => {
  const report = ok<FounderReport>("POST", "/api/founder/analyze", {
    company_id: index.founder_mode[0].company_id,
  });
  const keep = new Set(report.competitors.map((c) => c.company.id));
  assert.deepEqual(restrictToCompetitors(report, keep).skip.length, report.skip.length);

  const none = restrictToCompetitors(report, new Set());
  assert.equal(none.competitors.length, 0);
  assert.equal(none.skip.length, 0);
  assert.equal(none.pitch.length, report.pitch.length + report.skip.length);
  for (let i = 1; i < none.pitch.length; i++) {
    assert.ok(none.pitch[i - 1].score >= none.pitch[i].score);
  }
});

test("slush prep: job id, then the recorded stream ending in done", () => {
  const { job_id } = ok<{ job_id: string }>("POST", "/api/slush-prep", {
    company_id: index.founder_mode[0].company_id,
    investor_names: ["Maki.vc"],
  });
  const r = api.handle("GET", `/api/jobs/${job_id}/stream`);
  assert.equal(r.kind, "stream");
  const events = (r as { events: AgentEvent[] }).events;
  assert.equal(events.at(-1)?.type, "done");
  assert.ok(events.some((e) => e.type === "brief" && e.brief));
  assert.equal(status("GET", "/api/jobs/missing/stream"), 404);
  assert.equal(status("POST", "/api/slush-prep", { company_id: "x", investor_names: [] }), 422);
});

test("chat streams text chunks and ends with citations on done", () => {
  const r = api.handle("POST", "/api/chat", { message: "hi" });
  assert.equal(r.kind, "stream");
  const events = (r as { events: AgentEvent[] }).events;
  assert.ok(events.some((e) => e.type === "text"));
  assert.ok((events.at(-1)?.citations.length ?? 0) > 0);
  assert.equal(status("POST", "/api/chat", {}), 422);
});

