@import "tailwindcss";

/* Design system: frontend/DESIGN.md ("editorial broadsheet in a green room").
   Light only. Green is the single chromatic accent; everything else is ink on paper. */

:root {
  --background: #fafffa; /* Bone White: paper canvas, never pure #fff */
  --foreground: #000000; /* Typesetter Ink */
  --press: #121613; /* Press Black: dark sections, footer */
  --slate: #232924; /* Slate Verdant */
  --muted: #516254; /* Newsprint Gray: captions, helper text */
  --sage: #c8d2c8; /* Muted Sage: light text on dark; hairlines on light */
  --line: #d6ded6; /* hairline structure */
  --surface: #f0f6f0; /* quiet tint for hover / selected rows */
  --accent: #2bee4b; /* Highlighter Green: primary action, active underline */
  --moss: #93b799; /* Shadow Moss */
  --echo: #c4e4c9; /* Echo Green */
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-press: var(--press);
  --color-slate: var(--slate);
  --color-muted: var(--muted);
  --color-sage: var(--sage);
  --color-line: var(--line);
  --color-surface: var(--surface);
  --color-accent: var(--accent);
  --color-moss: var(--moss);
  --color-echo: var(--echo);
  --font-sans: var(--font-inter);
  --font-serif: var(--font-display);
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-inter), system-ui, sans-serif;
}

/* Small-caps micro-label: nav, buttons, section labels. */
@utility label {
  font-size: 11px;
  line-height: 1.1;
  font-weight: 550;
  letter-spacing: 0.01em;
  text-transform: uppercase;
}

/* Serif display headline: tight leading and tracking read as printed ink. */
@utility display {
  font-family: var(--font-display), Georgia, serif;
  font-weight: 400;
  line-height: 0.9;
  letter-spacing: -0.04em;
}

/* The one filled, saturated button; its shadow is green, never gray. */
@utility btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 5px;
  background: var(--accent);
  color: #000;
  padding: 16px 28px;
  font-size: 11px;
  font-weight: 550;
  letter-spacing: 0.01em;
  text-transform: uppercase;
  box-shadow: rgba(16, 94, 29, 0.45) 1px 8px 20px 0;
  &:disabled {
    background: var(--echo);
    box-shadow: none;
    cursor: not-allowed;
  }
}

/* Secondary action: ink outline, no fill, no shadow. */
@utility btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 5px;
  border: 1px solid var(--foreground);
  padding: 0 16px;
  font-size: 11px;
  font-weight: 550;
  letter-spacing: 0.01em;
  text-transform: uppercase;
  &:hover:not(:disabled) {
    background: var(--foreground);
    color: var(--background);
  }
  &:disabled {
    opacity: 0.35;
    cursor: not-allowed;
  }
}

:focus-visible {
  outline: 2px solid var(--foreground);
  outline-offset: 2px;
}

import type { Metadata } from "next";
import { Instrument_Serif, Inter } from "next/font/google";
import Link from "next/link";
import "./globals.css";

// Stand-ins for DESIGN.md's commercial faces: Inter for TWK Lausanne,
// Instrument Serif for the PP Mondwest display serif.
const inter = Inter({ variable: "--font-inter", subsets: ["latin"] });
const display = Instrument_Serif({
  variable: "--font-display",
  subsets: ["latin"],
  weight: "400",
  style: ["normal", "italic"],
});

export const metadata: Metadata = {
  title: "Pitchlist",
  description: "Who's a fit, and who has a conflict, from either side of the table. Built on Cala.",
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html lang="en" className={`${inter.variable} ${display.variable} h-full antialiased`}>
      <body className="flex min-h-full flex-col">
        <header className="border-b border-line">
          <div className="mx-auto flex h-16 w-full max-w-[1400px] items-center justify-between px-5 md:px-10">
            <Link href="/" className="text-lg font-semibold tracking-tight">
              <span className="border-b-2 border-accent">Pitch</span>list
            </Link>
            <span className="label text-muted">Every claim sourced from Cala</span>
          </div>
        </header>
        <main className="mx-auto w-full max-w-[1400px] flex-1 px-5 py-12 md:px-10 md:py-20">
          {children}
        </main>
        <footer className="bg-press text-background">
          <div className="mx-auto flex w-full max-w-[1400px] flex-wrap items-center justify-between gap-4 px-5 py-8 md:px-10">
            <span className="label">Pitchlist</span>
            <span className="label text-sage">Data: Cala · Junction 2026</span>
          </div>
          <div className="h-3 bg-accent" />
        </footer>
      </body>
    </html>
  );
}

import { HomeForm } from "@/components/HomeForm";

export default function Home() {
  return (
    <section>
      <p className="label text-muted">Fundraising, from either side of the table</p>
      <h1 className="display mt-5 max-w-4xl text-6xl md:text-8xl">
        Who&apos;s a fit, and who has a <em>conflict</em>.
      </h1>
      <p className="mt-8 max-w-xl text-lg leading-snug text-muted">
        Pitchlist walks Cala&apos;s graph from a company to its competitors, their rounds and the
        investors behind them, and shows a source for every claim.
      </p>
      <HomeForm />
    </section>
  );
}

// Small display helpers shared by the report screens.

/** "AEROSPACE_AND_DEFENSE" → "Aerospace and defense" */
export function prettyEnum(value: string): string {
  const words = value.toLowerCase().split(/[_\s]+/).filter(Boolean);
  if (words.length === 0) return value;
  const text = words.join(" ");
  return text.charAt(0).toUpperCase() + text.slice(1);
}

/** Remaining competitor IDs after the user removed some, in report order. */
export function keptCompetitorIds(competitorIds: string[], removed: ReadonlySet<string>): string[] {
  return competitorIds.filter((id) => !removed.has(id));
}

import assert from "node:assert/strict";
import { test } from "node:test";

import { keptCompetitorIds, prettyEnum } from "./format.ts";

test("prettyEnum", () => {
  assert.equal(prettyEnum("AEROSPACE_AND_DEFENSE"), "Aerospace and defense");
  assert.equal(prettyEnum("FINTECH"), "Fintech");
  assert.equal(prettyEnum(""), "");
});

test("keptCompetitorIds keeps order and drops removed", () => {
  assert.deepEqual(keptCompetitorIds(["a", "b", "c"], new Set(["b"])), ["a", "c"]);
  assert.deepEqual(keptCompetitorIds(["a"], new Set()), ["a"]);
  assert.deepEqual(keptCompetitorIds(["a"], new Set(["a"])), []);
});

"use client";

// Competitor chips (C5): one chip per competitor, the reason in a tooltip
// (hover, keyboard focus or tap), and a × to remove a wrong match.

import { useState } from "react";

import { SourceBadges } from "@/components/SourceBadge";
import type { Competitor } from "@/lib/types";

export function CompetitorChips({
  competitors,
  removed,
  onRemove,
  onRestore,
  disabled = false,
}: {
  competitors: Competitor[];
  removed: ReadonlySet<string>;
  onRemove: (id: string) => void;
  onRestore: (id: string) => void;
  disabled?: boolean;
}) {
  const kept = competitors.filter((c) => !removed.has(c.company.id));
  const gone = competitors.filter((c) => removed.has(c.company.id));

  return (
    <div>
      <ul className="flex flex-wrap gap-2">
        {kept.map((c) => (
          <Chip key={c.company.id} competitor={c} onRemove={onRemove} disabled={disabled} />
        ))}
      </ul>
      {gone.length > 0 && (
        <p className="mt-4 text-sm text-muted">
          <span className="label mr-2">Removed</span>
          {gone.map((c, i) => (
            <span key={c.company.id}>
              {i > 0 && ", "}
              <s>{c.company.name}</s>{" "}
              <button
                type="button"
                disabled={disabled}
                onClick={() => onRestore(c.company.id)}
                className="text-foreground underline underline-offset-4 disabled:opacity-40"
              >
                restore
              </button>
            </span>
          ))}
        </p>
      )}
    </div>
  );
}

function Chip({
  competitor,
  onRemove,
  disabled,
}: {
  competitor: Competitor;
  onRemove: (id: string) => void;
  disabled: boolean;
}) {
  const [open, setOpen] = useState(false);
  const { company, reason } = competitor;
  const tipId = `tip-${company.id}`;
  const meta = [company.stage, company.country].filter(Boolean).join(" · ");

  return (
    <li
      className="group relative"
      onMouseLeave={() => setOpen(false)}
      onKeyDown={(e) => e.key === "Escape" && setOpen(false)}
    >
      <span className="inline-flex items-center rounded-[5px] border border-foreground bg-background">
        <button
          type="button"
          aria-describedby={tipId}
          aria-expanded={open}
          onClick={() => setOpen((o) => !o)}
          className="py-1.5 pr-1 pl-3 text-sm font-medium"
        >
          {company.name}
        </button>
        <button
          type="button"
          disabled={disabled}
          onClick={() => onRemove(company.id)}
          aria-label={`Remove ${company.name} — not a real competitor`}
          title="Not a competitor? Remove it"
          className="px-2 py-1.5 text-muted hover:text-foreground disabled:opacity-40"
        >
          ×
        </button>
      </span>
      <div
        id={tipId}
        role="tooltip"
        className={`absolute top-full left-0 z-20 mt-2 w-72 border border-foreground bg-background p-4 text-left ${
          open ? "block" : "hidden group-focus-within:block group-hover:block"
        }`}
      >
        {meta && <p className="label text-muted">{meta}</p>}
        <p className="mt-2 text-sm leading-snug">{reason}</p>
        <p className="label mt-3 text-muted">Why a competitor: AI judgement</p>
        {company.description && (
          <p className="mt-3 line-clamp-4 border-t border-line pt-3 text-sm leading-snug text-muted">
            {company.description}
          </p>
        )}
        <div className="mt-3">
          <SourceBadges sources={company.sources} />
        </div>
      </div>
    </li>
  );
}

"use client";

// Founder report (C5 → C6): company header, competitor chips, then the Pitch and
// Skip lists. Removing competitors and pressing "Re-rank" calls
// /api/founder/analyze again with the remaining `competitor_ids`.

import Link from "next/link";
import { useCallback, useEffect, useRef, useState } from "react";

import { CompetitorChips } from "@/components/CompetitorChips";
import { SourceBadges } from "@/components/SourceBadge";
import { analyzeFounder, ApiError } from "@/lib/api";
import { keptCompetitorIds, prettyEnum } from "@/lib/format";
import type { Company, FounderReport } from "@/lib/types";

type Load =
  | { status: "loading" }
  | { status: "error"; message: string; notFound: boolean }
  | { status: "ready"; report: FounderReport; reranking: boolean; rerankError: string | null };

export function FounderReportView({ companyId }: { companyId: string }) {
  const [load, setLoad] = useState<Load>({ status: "loading" });
  const [removed, setRemoved] = useState<Set<string>>(new Set());
  const [narrowed, setNarrowed] = useState(false); // ranked against a user-edited list
  const abort = useRef<AbortController | null>(null);

  const run = useCallback(
    async (competitorIds?: string[]) => {
      abort.current?.abort();
      const ctrl = new AbortController();
      abort.current = ctrl;
      setLoad((prev) =>
        prev.status === "ready" && competitorIds
          ? { ...prev, reranking: true, rerankError: null }
          : { status: "loading" },
      );
      try {
        const report = await analyzeFounder(
          { company_id: companyId, ...(competitorIds ? { competitor_ids: competitorIds } : {}) },
          ctrl.signal,
        );
        if (ctrl.signal.aborted) return;
        setLoad({ status: "ready", report, reranking: false, rerankError: null });
        setRemoved(new Set());
        setNarrowed(Boolean(competitorIds));
      } catch (err) {
        if (ctrl.signal.aborted) return;
        const message = err instanceof ApiError ? err.message : "Something went wrong.";
        setLoad((prev) =>
          prev.status === "ready" && competitorIds
            ? { ...prev, reranking: false, rerankError: message }
            : { status: "error", message, notFound: err instanceof ApiError && err.status === 404 },
        );
      }
    },
    [companyId],
  );

  useEffect(() => {
    void run();
    return () => abort.current?.abort();
  }, [run]);

  if (load.status === "loading") return <LoadingReport />;
  if (load.status === "error") {
    return (
      <div className="max-w-xl">
        <p className="label text-muted">Founder report</p>
        <h1 className="display mt-4 text-5xl">
          {load.notFound ? "We couldn't find that company." : "The report didn't load."}
        </h1>
        <p className="mt-6 border-l-2 border-foreground pl-3">{load.message}</p>
        <div className="mt-8 flex gap-3">
          {!load.notFound && (
            <button type="button" className="btn-primary" onClick={() => void run()}>
              Try again
            </button>
          )}
          <Link href="/" className="btn-ghost h-[47px]">
            Search again
          </Link>
        </div>
      </div>
    );
  }

  const { report, reranking, rerankError } = load;
  const ids = report.competitors.map((c) => c.company.id);
  const kept = keptCompetitorIds(ids, removed);

  return (
    <div>
      <CompanyHeader company={report.company} />

      <section className="mt-16 border-t border-line pt-8">
        <div className="flex flex-wrap items-baseline justify-between gap-4">
          <div>
            <p className="label">Competitors · {kept.length}</p>
            <p className="mt-2 max-w-xl text-sm text-muted">
              Investors who backed these go on the Skip list. Hover a name to see why it counts;
              remove the ones that don&apos;t, then re-rank.
            </p>
          </div>
          <div className="flex items-center gap-4">
            {narrowed && removed.size === 0 && (
              <button
                type="button"
                disabled={reranking}
                onClick={() => void run()}
                className="text-sm underline underline-offset-4 disabled:opacity-40"
              >
                Reset to all competitors
              </button>
            )}
            {removed.size > 0 && (
              <button
                type="button"
                disabled={reranking}
                onClick={() => void run(kept)}
                className="btn-primary"
              >
                {reranking ? "Re-ranking…" : `Re-rank with ${kept.length}`}
              </button>
            )}
          </div>
        </div>
        {rerankError && (
          <p className="mt-4 border-l-2 border-foreground pl-3 text-sm">
            Re-ranking failed: {rerankError}
          </p>
        )}
        <div className="mt-6">
          {report.competitors.length === 0 ? (
            <p className="text-muted">
              No direct competitors found in Cala, so no investor has a conflict yet.
            </p>
          ) : (
            <CompetitorChips
              competitors={report.competitors}
              removed={removed}
              disabled={reranking}
              onRemove={(id) => setRemoved((s) => new Set(s).add(id))}
              onRestore={(id) =>
                setRemoved((s) => {
                  const next = new Set(s);
                  next.delete(id);
                  return next;
                })
              }
            />
          )}
        </div>
      </section>

      <section
        className={`mt-16 border-t border-line pt-8 transition-opacity ${reranking ? "opacity-40" : ""}`}
        aria-busy={reranking}
      >
        {/* C6 replaces this summary with the Pitch and Skip lists. */}
        <p className="label">Investors</p>
        <p className="display mt-4 text-5xl">
          {report.pitch.length} to pitch, {report.skip.length} to skip.
        </p>
      </section>
    </div>
  );
}

function CompanyHeader({ company }: { company: Company }) {
  const facts = [
    company.stage,
    company.country,
    ...company.industries.map(prettyEnum),
    company.total_funding_text && `${company.total_funding_text} raised`,
  ].filter(Boolean);
  return (
    <header>
      <p className="label text-muted">Founder report</p>
      <h1 className="display mt-4 text-6xl md:text-8xl">{company.name}</h1>
      {facts.length > 0 && (
        <p className="label mt-6 flex flex-wrap gap-x-4 gap-y-1 text-muted">
          {facts.map((f) => (
            <span key={f as string}>{f}</span>
          ))}
        </p>
      )}
      {company.description && (
        <p className="mt-4 max-w-2xl text-lg leading-snug">{company.description}</p>
      )}
      <div className="mt-4">
        <SourceBadges sources={company.sources} />
      </div>
    </header>
  );
}

function LoadingReport() {
  return (
    <div aria-busy="true" aria-live="polite">
      <p className="label text-muted">Founder report</p>
      <div className="mt-4 h-20 w-2/3 max-w-xl animate-pulse bg-surface" />
      <p className="mt-8 max-w-xl text-muted">
        Finding your competitors in Cala, then the rounds they raised and the investors behind
        them. This can take a few seconds.
      </p>
      <div className="mt-12 flex gap-2">
        {[0, 1, 2, 3].map((i) => (
          <div key={i} className="h-9 w-28 animate-pulse rounded-[5px] bg-surface" />
        ))}
      </div>
    </div>
  );
}

import { Suspense } from "react";

import { FounderReportView } from "@/components/FounderReportView";

type Params = PageProps<"/founder/[companyId]">["params"];

export default function FounderPage({ params }: { params: Params }) {
  return (
    <Suspense fallback={null}>
      <Report params={params} />
    </Suspense>
