// Wording for investor cards (C6). Pure, so the rules are unit-tested.

import { formatSourceDate } from "./sources";
import type { Conflict, InvestorScore } from "./types";

const plural = (n: number, one: string, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;

/** "Leads in your space", honest about how much Cala says about who led. */
export function leadSummary(s: InvestorScore): string {
  const rounds = s.rounds_in_space;
  if (rounds === 0) return "No rounds in your space yet";
  switch (s.lead_data) {
    case "known":
      return `Led ${s.leads_in_space} of ${plural(rounds, "round")} in your space`;
    case "partial":
      return `Led at least ${s.leads_in_space} of ${plural(rounds, "round")} in your space (lead known for some)`;
    default:
      return `In ${plural(rounds, "round")} in your space · Cala doesn't say who led`;
  }
}

/** "Still active": last lead and deal count, skipping what's unknown. */
export function activitySummary(s: InvestorScore): string {
  const last = formatSourceDate(s.last_lead_date);
  const parts = [last ? `Last lead ${last}` : "No lead on record"];
  if (s.deals_last_12m !== null) parts.push(`${plural(s.deals_last_12m, "deal")} in the last 12 months`);
  return parts.join(" · ");
}

/** The reason an investor is on the Skip list, in one line. */
export function conflictText(c: Conflict): string {
  if (c.kind === "BOARD") {
    return c.via_person
      ? `${c.via_person.name} sits on the board of your competitor ${c.competitor.name}`
      : `Has a seat on the board of your competitor ${c.competitor.name}`;
  }
  return `Backed your competitor ${c.competitor.name}`;
}

import assert from "node:assert/strict";
import { test } from "node:test";

import { activitySummary, conflictText, leadSummary } from "./investor.ts";
import type { Conflict, EntityRef, InvestorScore } from "./types.ts";

const ref = (name: string, type = "Organization"): EntityRef => ({
  id: name.toLowerCase(),
  name,
  type,
  description: null,
});

const score = (over: Partial<InvestorScore>): InvestorScore => ({
  investor: ref("Maki.vc"),
  score: 50,
  conflicts: [],
  leads_in_space: 0,
  rounds_in_space: 0,
  lead_data: "unknown",
  last_lead_date: null,
  deals_last_12m: null,
  warm_paths: [],
  reasons: [],
  ...over,
});

test("leadSummary follows lead_data", () => {
  assert.equal(
    leadSummary(score({ leads_in_space: 2, rounds_in_space: 2, lead_data: "known" })),
    "Led 2 of 2 rounds in your space",
  );
  assert.equal(
    leadSummary(score({ leads_in_space: 0, rounds_in_space: 1, lead_data: "known" })),
    "Led 0 of 1 round in your space",
  );
  assert.equal(
    leadSummary(score({ leads_in_space: 1, rounds_in_space: 4, lead_data: "partial" })),
    "Led at least 1 of 4 rounds in your space (lead known for some)",
  );
  assert.equal(
    leadSummary(score({ rounds_in_space: 3, lead_data: "unknown" })),
    "In 3 rounds in your space · Cala doesn't say who led",
  );
  assert.equal(leadSummary(score({})), "No rounds in your space yet");
});

test("activitySummary skips unknowns", () => {
  assert.equal(
    activitySummary(score({ last_lead_date: "2026-06-09", deals_last_12m: 5 })),
    "Last lead 9 Jun 2026 · 5 deals in the last 12 months",
  );
  assert.equal(activitySummary(score({ deals_last_12m: 1 })), "No lead on record · 1 deal in the last 12 months");
  assert.equal(activitySummary(score({})), "No lead on record");
});

test("conflictText", () => {
  const base: Conflict = { kind: "PORTFOLIO", competitor: ref("Kova Labs", "Company"), via_person: null, sources: [] };
  assert.equal(conflictText(base), "Backed your competitor Kova Labs");
  assert.equal(
    conflictText({ ...base, kind: "BOARD", via_person: ref("Jane Doe", "Person") }),
    "Jane Doe sits on the board of your competitor Kova Labs",
  );
  assert.equal(
    conflictText({ ...base, kind: "BOARD" }),
    "Has a seat on the board of your competitor Kova Labs",
  );
});

// Investor cards for the founder report (C6). Pitch cards lead with fit; Skip
// cards lead with the conflict, because that is the reason they are there.

import { SourceBadges } from "@/components/SourceBadge";
import { activitySummary, conflictText, leadSummary } from "@/lib/investor";
import type { InvestorScore, Reason } from "@/lib/types";

const VISIBLE_REASONS = 3;

export function PitchCard({ item, rank }: { item: InvestorScore; rank: number }) {
  return (
    <article className="grid grid-cols-[2.5rem_1fr] gap-x-4 border-t border-line py-6 md:grid-cols-[4rem_1fr_7rem]">
      <p className="display text-3xl text-muted md:text-4xl" aria-label={`Rank ${rank}`}>
        {String(rank).padStart(2, "0")}
      </p>
      <div className="min-w-0">
        <Name item={item} />
        <Signals item={item} />
        <Reasons reasons={item.reasons} />
        <WarmPaths paths={item.warm_paths} />
      </div>
      <Score value={item.score} />
    </article>
  );
}

export function SkipCard({ item }: { item: InvestorScore }) {
  return (
    <article className="border-t border-line py-6">
      <div className="border-l-4 border-press pl-4 md:pl-6">
        <Name item={item} />
        <ul className="mt-3 space-y-2">
          {item.conflicts.map((c, i) => (
            <li key={`${c.competitor.id}-${c.kind}-${i}`}>
              <p className="text-lg leading-snug font-medium">
                <span className="label mr-2 inline-block rounded-[5px] bg-press px-1.5 py-1 align-middle text-background">
                  {c.kind === "BOARD" ? "Board conflict" : "Conflict"}
                </span>
                {conflictText(c)}
              </p>
              <div className="mt-1.5">
                <SourceBadges sources={c.sources} max={2} />
              </div>
            </li>
          ))}
        </ul>
        <details className="group mt-4">
          <summary className="label cursor-pointer list-none text-muted hover:text-foreground [&::-webkit-details-marker]:hidden">
            <span className="group-open:hidden">+ Other signals · fit {Math.round(item.score)}/100</span>
            <span className="hidden group-open:inline">− Other signals</span>
          </summary>
          <Signals item={item} />
          <Reasons reasons={item.reasons} all />
          <WarmPaths paths={item.warm_paths} />
        </details>
      </div>
    </article>
  );
}

function Name({ item }: { item: InvestorScore }) {
  return (
    <h3 className="flex flex-wrap items-baseline gap-x-3 gap-y-1">
      <span className="text-xl font-medium tracking-tight">{item.investor.name}</span>
      <span className="label text-muted">{item.investor.type === "Person" ? "Angel" : item.investor.type}</span>
    </h3>
  );
}

function Signals({ item }: { item: InvestorScore }) {
  return (
    <p className="mt-2 text-sm text-muted">
      {leadSummary(item)}
      <span aria-hidden="true"> · </span>
      {activitySummary(item)}
    </p>
  );
}

function Score({ value }: { value: number }) {
  const v = Math.round(value);
  return (
    <div className="col-start-2 mt-4 md:col-start-auto md:mt-0 md:text-right">
      <p className="display text-4xl text-muted md:text-5xl">{v}</p>
      <p className="label mt-1 text-muted">Fit / 100</p>
      <div className="mt-2 h-1 w-24 bg-surface md:ml-auto" aria-hidden="true">
        <div className="h-1 bg-accent" style={{ width: `${Math.max(0, Math.min(100, v))}%` }} />
      </div>
    </div>
  );
}

function Reasons({ reasons, all = false }: { reasons: Reason[]; all?: boolean }) {
  if (reasons.length === 0) return null;
  const shown = all ? reasons : reasons.slice(0, VISIBLE_REASONS);
  const rest = all ? [] : reasons.slice(VISIBLE_REASONS);
  return (
    <div className="mt-4">
      <ReasonList reasons={shown} />
      {rest.length > 0 && (
        <details className="group mt-2">
          <summary className="label cursor-pointer list-none text-muted hover:text-foreground [&::-webkit-details-marker]:hidden">
            <span className="group-open:hidden">+ {rest.length} more</span>
            <span className="hidden group-open:inline">− Fewer</span>
          </summary>
          <ReasonList reasons={rest} />
        </details>
      )}
    </div>
  );
}

function ReasonList({ reasons }: { reasons: Reason[] }) {
  return (
    <ul className="space-y-1.5">
      {reasons.map((r, i) => (
        <li key={`${r.text}-${i}`} className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm">
          <span>{r.text}</span>
          <SourceBadges sources={r.sources} />
        </li>
      ))}
    </ul>
  );
}

function WarmPaths({ paths }: { paths: Reason[] }) {
  if (paths.length === 0) return null;
  return (
    <div className="mt-4">
      <p className="label">Warm path</p>
      <ul className="mt-1.5 space-y-1.5">
        {paths.map((p, i) => (
          <li key={`${p.text}-${i}`} className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm">
            <span className="border-b-2 border-accent">{p.text}</span>
            {/* co_investors() has no sources yet (notes/B.md): say where it comes from instead of "No source". */}
            {p.sources.length > 0 ? (
              <SourceBadges sources={p.sources} />
            ) : (
              <span className="text-xs text-muted">from co-investment data</span>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

